# quiz-engine.R — for BASE-module pages (outside the workshops).
# The workshops load the quiz engine with include-after-body; a base page cannot, because its own
# include-after-body could replace the site-wide one in _quarto.yml. So the page calls quiz_engine()
# in a chunk with  #| echo: false  and  #| output: asis , which writes the inlined engine
# (assets/quiz-inline.html, generated by scripts/sync_workshop_assets.sh) into the page.
quiz_engine <- function() {
  for (up in c("assets", "../assets", "../../assets", "../../../assets")) {
    f <- file.path(up, "quiz-inline.html")
    if (file.exists(f)) {
      cat("\n```{=html}\n", paste(readLines(f, warn = FALSE, encoding = "UTF-8"), collapse = "\n"), "\n```\n", sep = "")
      return(invisible(TRUE))
    }
  }
  stop("assets/quiz-inline.html not found: run scripts/sync_workshop_assets.sh")
}
